const error = $json;
const workflowName = error.workflow?.name || 'Unknown';
const workflowId = error.workflow?.id || 'Unknown';
const executionId = error.execution?.id || 'Unknown';
const errorMessage = error.execution?.error?.message || 'Unknown error';
const errorNode = error.execution?.lastNodeExecuted || 'Unknown';
const errorStack = error.execution?.error?.stack || '';
const errorTime = new Date().toISOString();

const htmlContent = `<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
  <div style="background: #dc3545; padding: 20px; border-radius: 10px 10px 0 0; text-align: center;">
    <h1 style="color: white; margin: 0;">⚠️ Workflow Error Alert</h1>
    <p style="color: white; margin: 5px 0 0 0;">Layla WhatsApp AI Assistant encountered an error</p>
  </div>
  <div style="padding: 20px; border: 1px solid #ddd; border-top: none; border-radius: 0 0 10px 10px;">
    <h2 style="color: #333; border-bottom: 2px solid #dc3545; padding-bottom: 10px;">Error Details</h2>
    <table style="width: 100%; border-collapse: collapse;">
      <tr><td style="padding: 8px; font-weight: bold; width: 180px;">Workflow:</td><td style="padding: 8px;">${workflowName} (ID: ${workflowId})</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Execution ID:</td><td style="padding: 8px;">${executionId}</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Failed Node:</td><td style="padding: 8px; color: #dc3545; font-weight: bold;">${errorNode}</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Error Message:</td><td style="padding: 8px;">${errorMessage}</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Time:</td><td style="padding: 8px;">${errorTime}</td></tr>
    </table>
    <h2 style="color: #333; border-bottom: 2px solid #dc3545; padding-bottom: 10px; margin-top: 20px;">Stack Trace</h2>
    <pre style="background: #f8f9fa; padding: 15px; border-radius: 5px; overflow-x: auto; font-size: 12px; white-space: pre-wrap;">${errorStack.substring(0, 2000)}</pre>
    <h2 style="color: #333; border-bottom: 2px solid #dc3545; padding-bottom: 10px; margin-top: 20px;">Action Required</h2>
    <ul style="padding-left: 20px;">
      <li style="padding: 5px 0;">Check the n8n workflow: <a href="https://n8n.horizonafrica.co.za/workflow/${workflowId}">Open in n8n</a></li>
      <li style="padding: 5px 0;">Review the execution details: <a href="https://n8n.horizonafrica.co.za/execution/${executionId}">View execution</a></li>
      <li style="padding: 5px 0;">Fix the error and re-publish the workflow</li>
    </ul>
    <hr style="margin-top: 20px; border: none; border-top: 1px solid #ddd;">
    <p style="color: #999; font-size: 12px; text-align: center;">This alert was generated automatically by the n8n Error Trigger</p>
  </div>
</div>`;

return { json: {
  sender: { name: 'Horizon Africa AI', email: 'keshlan@horizonafrica.co.za' },
  to: [{ email: 'sifosman@gmail.com', name: 'Sif' }],
  subject: '⚠️ Layla Error Alert: ' + workflowName + ' - ' + errorNode,
  htmlContent: htmlContent
} };
